// Buffer kezelése és szétválasztás HTTP fejléc és body között
const data = msg.payload.toString('utf8');

// Különböző sorvége karakterek kezelése
const blankLinePattern = /\r?\n\r?\n/;
const blankLineMatch = data.match(blankLinePattern);

if (!blankLineMatch) {
    node.warn('Invalid HTTP format - no blank line found');
    node.warn('Full message: ' + data);
    return null;
}

const blankLineIndex = blankLineMatch.index;
const blankLineLength = blankLineMatch[0].length;

const headers = data.substring(0, blankLineIndex).split(/\r?\n/);
const body = data.substring(blankLineIndex + blankLineLength).trim();

try {
    // Content-Length ellenőrzése
    const contentLengthHeader = headers.find(h => h.toLowerCase().startsWith('content-length:'));
    const contentLength = contentLengthHeader ? parseInt(contentLengthHeader.split(':')[1].trim()) : 0;

    if (body.length < contentLength) {
        node.warn(`Incomplete message body. Expected: ${contentLength}, got: ${body.length}`);
        return null;
    }

    // JSON parse
    const jsonData = JSON.parse(body);

    // Adatok normalizálása
    msg.payload = {
        deviceId: jsonData.subDevId,
        outlet: jsonData.outlet,
        current: jsonData.current / 1000,    // mA -> A
        voltage: jsonData.voltage / 100,     // 0.1V -> V
        activePower: jsonData.actPow / 10,   // 0.1W -> W
        reactivePower: jsonData.reactPow / 10,
        apparentPower: jsonData.apparentPow / 10,
        timestamp: new Date().toISOString(),
        rawHeaders: headers
    };

    node.log("Successfully parsed message from: " + (msg.remoteAddress || 'unknown'));
    return msg;

} catch (err) {
    node.error('Error parsing message: ' + err.message);
    node.error('Problematic body: ' + body);
    return null;
}

