    out0 = { topic: "CH0", payload: state };
} else if (target === "CH2SW") {
    out1 = { topic: "CH1", payload: state };
} else if (target === "CH3SW") {
    out2 = { topic: "CH2", payload: state };
} else if (target === "CH4SW") {
    out3 = { topic: "CH3", payload: state };
}

return [out0, out1, out2, out3];

let ch = msg.topic; // "CH0", "CH1", "CH2", "CH3"
let state = (msg.payload === true || msg.payload === "on" || msg.payload === 1);

let btIndex = -1;
if (ch === "CH0") btIndex = 0;
else if (ch === "CH1") btIndex = 1;
else if (ch === "CH2") btIndex = 2;
else if (ch === "CH3") btIndex = 3;

if (btIndex === -1) {
    return null;
}

let binVal = state ? 1 : 0;
let nextionCmd = `p[3].bt${btIndex}.val=${binVal}`;

let term = Buffer.from([0xFF, 0xFF, 0xFF]);
let cmdBuf = Buffer.from(nextionCmd, 'ascii');

msg.payload = Buffer.concat([cmdBuf, term]);
return msg;
